    Ok(result) => println!("Success: {:?}", result),
    Err(PrivoxError::VaultError(e)) => eprintln!("Vault error: {}", e),
    Err(KnowledgeError::NotFound(msg)) => eprintln!("Not found: {}", msg),
    Err(e) => eprintln!("Error: {}", e),
}
```

